import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Sekai: A Video Dataset towards World Exploration","description":"","frontmatter":{"title":"Sekai: A Video Dataset towards World Exploration","arxiv":"2506.15675","date":"2025-06-18","authors":"Zhen Li, Chuanhao Li, Xiaofeng Mao, Shaoheng Lin, Ming Li, Shitian Zhao, Zhaopan Xu, Xinyue Li, Yukang Feng, Jianwen Sun, Zizhen Li, Fanrui Zhang, Jiaxin Ai, Zhixiang Wang, Yuwei Wu, Tong He, Jiangmiao Pang, Yu Qiao, Yunde Jia, Kaipeng Zhang","categories":"cs.CV, cs.AI","topics":"世界探索数据集, 第一人称视频, 相机轨迹标注","outline":[2,2]},"headers":[],"relativePath":"papers/2506.15675.md","filePath":"papers/2506.15675.md","lastUpdated":null}'),e={name:"papers/2506.15675.md"};function l(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="sekai-a-video-dataset-towards-world-exploration" tabindex="-1">Sekai: A Video Dataset towards World Exploration <a class="header-anchor" href="#sekai-a-video-dataset-towards-world-exploration" aria-label="Permalink to &quot;Sekai: A Video Dataset towards World Exploration&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.15675" target="_blank" rel="noreferrer">2506.15675</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-18</td></tr><tr><td><strong>作者</strong></td><td>Zhen Li, Chuanhao Li, Xiaofeng Mao, Shaoheng Lin, Ming Li, Shitian Zhao, Zhaopan Xu, Xinyue Li, Yukang Feng, Jianwen Sun, Zizhen Li, Fanrui Zhang, Jiaxin Ai, Zhixiang Wang, Yuwei Wu, Tong He, Jiangmiao Pang, Yu Qiao, Yunde Jia, Kaipeng Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把 101 个国家、750 座城市的 5000+ 小时第一人称行走与无人机视频，配上位置、场景、天气、人群密度、长 caption 和逐帧相机轨迹六类标注，做成专供&quot;世界探索&quot;训练的数据集，并给出按质量和多样性筛出 400 小时 HQ 子集的采样模块。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>世界生成模型这条路线里，第一幕是<strong>世界探索</strong>：给一张图或一段文字，构造出一个可以不受限地走进去、四处看的动态世界。技术上最顺的实现方式是相机可控的视频生成——因为键盘鼠标输入可以直接换算成相机轨迹。</p><p>但作者指出瓶颈不在模型，在<strong>数据</strong>。现有视频生成数据集（OpenVid-1M、Panda-70M、MiraData）不是为探索设计的，四个缺陷叠在一起让它们不可用：地点覆盖有限、单条视频太短、场景偏静态、以及缺少探索类标注（相机轨迹）和世界类标注（位置、天气、场景）。</p><p>第三条和第四条最要命。没有相机轨迹标注，相机可控生成就只能靠规则把离散按键硬映射成位姿，模型学到的是一个粗糙近似；视频太短，模型就学不到&quot;走出去再走回来&quot;这个尺度上的空间一致性。这两件事恰恰是世界探索的核心能力。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把视频生成数据集分成两类逐一检视。</p><p><strong>特定场景类</strong>：UCF-101、Taichi-HD、SkyTimelapse、FaceForensics++、ChronoMagic、CelebV-HQ。共同问题是总时长不足 800 小时、单条视频平均短于 20 秒，且大多没有标注（ChronoMagic 之类少数提供 caption）。</p><p><strong>开放场景类</strong>规模上进了一步：OpenSoraPlan-V1.0 总计 274 小时并带详细 caption，OpenVid-1M 总计 2100 小时并给长 caption。但作者的批评很精确：<strong>单条视频平均时长仍不超过 25 秒，而且只有 caption 一种标注</strong>。MiraData 把平均时长提到 72.1 秒，是最接近的对手，但作者认为对世界探索仍然不够长，且同样缺少探索标注（相机位姿、键鼠输入）和世界标注（位置、时间、天气）。</p><p>这个批评的关键不是&quot;数据不够多&quot;，而是<strong>标注维度不对</strong>。相机可控生成需要的监督信号是逐帧位姿，而所有开放场景数据集都不提供——不是因为大家没想到，而是因为在野外视频上做可靠的相机位姿估计本身就是难题（手持抖动、动态前景、无标定相机）。这解释了为什么这个缺口一直没被填上。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2025 年上半年，几件事恰好凑齐了。第一，YouTube 上有大量高质量 citywalk 和 FPV 无人机视频，时长 30 分钟到 12 小时、1080P、30–60 FPS，第一人称、连续、覆盖全球——这是一座现成的矿，缺的只是采集与清洗管线。第二，动态场景下的 SfM/SLAM 刚刚变得可用：MegaSaM 能在随手拍的动态视频上做出稳定的相机与深度估计，VGGT 提供了前馈式的快速替代，Video Depth Anything 解决了单目深度的时序抖动。第三，大 VLM（Qwen2.5-VL 72B）已经可以低成本地做多维分类和长描述标注。</p><p>于是路径清晰了：矿在那里、挖矿工具刚成熟，剩下的是把管线搭对。但还有一个隐忧——YouTube 视频没有真值标注，所有位姿、类别都是模型估计的，质量无法保证。这里作者补了一手很聪明的设计：<strong>再录一份游戏数据</strong>。Lushfoil Photography Sim 基于 UE5、支持步行和第一人称无人机探索真实地貌，画面接近照片级，而且通过 RE-UE4SS 这类 UE 脚本系统可以直接读出相机位姿——这就得到了一份带<strong>真值标注</strong>的对照集，用来校验和补足真实数据。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>世界探索模型需要的不是&quot;更多视频&quot;，而是&quot;<strong>长、连续、第一人称、且知道相机在哪</strong>&quot;的视频。前三条决定了模型能不能学到跨越空间的一致性，第四条决定了它能不能被精确操控。这四条同时满足的数据在公开集里不存在，但在 YouTube 的 citywalk/FPV 频道里天然存在，只是需要一套能把它们从 8000 多小时原始素材里清洗和标注出来的管线。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>整条链路分四段：采集、预处理、标注、采样。</p><p><strong>采集</strong>。人工从优质 UP 主收集 URL 并按关键词（walk、drone、HDR、4K）扩展，最终锁定 10471 小时行走视频（带立体声）和 628 小时无人机视频，全部近三年发布、至少 1080P、30–60 FPS。因网络与损坏问题实际下载到 8409 小时行走 + 214 小时无人机，共 8623 小时。游戏侧用 OBS Studio 在 Lushfoil Photography Sim 里录制 40+ 小时 1080P 30FPS（8–12 Mbps）素材，覆盖多种地点与天气。</p><p><strong>预处理</strong>。原始视频首尾各裁 2 分钟去片头片尾。用 TransNetV2（阈值 0.4）做镜头边界检测，作者把它重构为 GPU 版本（PyNVideoCodec 解码 + CVCUDA 做色彩空间转换和直方图），快了 5 倍；每个镜头首尾再裁 5 秒。切成一分钟片段（不足一分钟丢弃），重编码为 720p / 30fps / H.265 / 4 Mbps，抽检 PSNR 高于 35 表示无可感知退化；行走视频保留音轨，AAC 48kHz 重编码后与视频复用。随后是四道过滤：亮度（YUV 亮度通道，连续 15 帧以上极亮或极暗即剔除，过滤掉 300 小时，对游戏数据尤其必要，因为引擎的简化光照容易产生极端帧）、质量（COVER 的 technical quality，去掉最低 10%）、字幕（VideoSubFinder 检测画面下三分之一，硬字幕持续超过 0.75 秒即剔除，约 5%）、以及轨迹（见下）。预处理后得到 6620 小时 Sekai-Real 和 60 小时 Sekai-Game 片段。</p><p><strong>轨迹过滤</strong>的三条启发式规则值得单独列，因为它们直接定义了什么叫&quot;不合理的相机运动&quot;：10 秒窗口内出现多次超过 150° 的方向骤转；相邻两帧视角变化超过 60°；某帧位移超过包含该帧的 30 帧平均位移的 5 倍。</p><p><strong>标注</strong>。位置：用 YouTube Data API 拿标题和描述，GPT-4o 抽取每个章节的规范化地点并附 ISO 3166 国家/地区码，再用区间树按时间戳把片段匹配到章节，无法唯一匹配的约 8% 直接丢弃。类别与 caption：两阶段——先沿场景类型、天气、时间、人群密度四个正交维度分类（模型不确定时允许弃权），再把类别标签、位置信息和视频帧一起送进 prompt 生成时序化的动作与场景描述；每 2 秒抽一帧，用 Qwen2.5-VL 72B，vLLM 推理服务 + Nginx 负载均衡，最终 caption 平均超过 176 词。相机轨迹：对比过 DPVO（视觉里程计）、MegaSaM（深度视觉 SLAM）、VGGT（3D transformer）三类方法后选定 MegaSaM，并把其中的 Depth Anything 换成时序更一致的 Video Depth Anything，同时改造官方实现支持跨机多卡并行。游戏侧则用 RE-UE4SS 的 Lua API 直接实时抓取相机位姿、统一相机系统配置、隐藏 GUI，位姿再做延迟补偿与插值对齐视频帧。</p><p><strong>采样</strong>。全量训练成本过高，所以设计了一个按计算预算筛顶层片段的模块，最终产出 400 小时的 <strong>Sekai-Real-HQ</strong>。质量维度用 COVER 的美学与语义两项分数求和，取前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.7</span></span></span></span>。多样性维度依次跑四个模块：内容多样性（InternVideo2 提 embedding，按国家/地区做 mini-batch K-Means 聚类，簇内按质量分排序后迭代地采一条、删掉与之最相似的一条，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">co</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">70%</span></span></span></span>）、地点多样性（按各城市片段数升序依次配额，配额超过实际数量时把缺口按比例重分配给剩余城市，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">oc</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">60%</span></span></span></span>）、类别多样性（四个类别维度做逆频率加权采样，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">60%</span></span></span></span>）、轨迹多样性（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mathnormal mtight">a</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">75%</span></span></span></span>）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文以数据工程为主，形式化推导有限，只在采样模块里有两处值得展开。</p><p><strong>逆频率加权采样</strong>。设某片段在四个类别维度（天气、场景、时间、人群密度）上的标签分别为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">4</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，每个标签在全集中的频率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。作者假设四个维度相互独立，把该片段的初始采样概率取为各维度概率的乘积，其中每一维的概率与其标签频率成反比：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord text"><span class="mord">clip</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∝</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1032em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∏</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>再归一化到和为 1，做无放回采样直到取够 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 比例。直觉是：一个&quot;雪天 + 室内 + 夜晚 + 人群稀疏&quot;的片段在四个维度上都罕见，乘积会把它的采样概率推得很高，从而对抗长尾。这里&quot;独立性假设&quot;是明显的近似——雪天和夜晚显然相关——但对于粗粒度的配平而言够用。</p><p><strong>轨迹抖动的度量</strong>。轨迹多样性采样用两个量刻画一条轨迹：方向向量（起点到终点的位移）和整体抖动。抖动定义为每 30 帧计算一次位置方差、再取其欧氏范数。方向向量被离散化到球面上的 bin，抖动值也离散化到 bin，两者做联合分组，最后在每组内按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">am</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mathnormal mtight">a</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 均匀采样。这个设计的意图是：只看方向会让&quot;直线前进&quot;这一类占据绝大多数（走路视频天然如此），加上抖动维度后，&quot;平稳直行&quot;和&quot;边走边东张西望&quot;就被分到不同组，各自保留配额。论文给出的证据是 Sekai-Real-HQ 的抖动分布比采样前更平滑。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：自动标注可信吗？</strong> 三项独立验证。位置：随机抽 500 条视频，由共同作者用在线地图逐一核对三类问题（遗漏或错误合并、时间戳与地点错位、地点是推断而非明说），结果问题率低于 5%——作者归因于标题描述本身信息丰富，GPT-4o 只需抽取而非推断。相机轨迹：在 100 条行走 + 100 条无人机片段上比较 MegaSAM 和 VGGT，结论是 MegaSAM 因为有全局优化模块轨迹更平滑，VGGT 推理更快但质量更低；由于训练更需要平滑轨迹，选 MegaSAM。类别：随机抽 500 条人工标注，与 Qwen2.5-VL 的一致率超过 90%；分歧主要出现在 cloudy/foggy 与 rainy 之间，作者的分析很有意思——<strong>雨在单帧里往往不可见，要连续几帧才看得出来</strong>，说明大 VLM 的时序视觉推理仍是弱项。室内场景因为灯光干扰天气和时间判断，被排除在该分析之外。</p><p><strong>问题二：在这份数据上微调能带来什么？</strong> 用 SkyReels-V2-14B 的 T2V 和 I2V 版本，保持原架构与训练配置，在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">544</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">960</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">49</span></span></span></span>、16 fps、batch 1、lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、8 张 H100 上训 20000 步；测试集是把 Sekai-Real-HQ 分十折、取最后两折为候选，再由独立标注者人工挑 50 条以保证多样性；指标用 VBench（I2V 额外用 VBench++ 的 I2V Subject / I2V Background）。T2V 从 5000 步到 20000 步，Overall Score 4.26 → 4.34，subject consistency 91.93% → 96.02%，aesthetic 48.38% → 52.09%，imaging 57.04% → 60.90%。I2V 从 5000 步到 17500 步，Overall 6.10 → 6.29，I2V Subject 93.74% → 97.27%，I2V Background 93.85% → 96.65%。</p><p>有一个反直觉的现象作者主动解释了：<strong>Dynamic Degree 在早期达峰后下降</strong>（T2V 90.67% → 78.66%，I2V 100% → 85%）。作者的说法是这是一次再平衡——模型从早期夸张运动转向更锐利的细节和更干净的帧，运动幅度变得更适中而整体质量继续上升。这是一个诚实但未经独立验证的解释。</p><p><strong>问题三：相机轨迹标注是否真的比规则映射好？</strong> 这是全文最直接的价值验证。baseline 是 Wan2.1-Fun-V1.1-1.3B-Control-Camera 的原做法——把离散动作输入按规则换算成相机位姿，再算 Plücker embedding 注入模型；对照组直接用 Sekai 标注的逐帧真实位姿微调 2 个 epoch。指标用 CameraCtrl 的 TransErr 和 RotErr，做法是用 Mega-SAM 从生成视频里反解轨迹再与输入轨迹比。在 Sekai-Real 无人机部分上：TransErr 28.32 → 17.19（降 11.13），RotErr 27.2 → 19.89（降 7.31），同时背景一致性 94.85% → 95.56%、美学 58.25% → 59.18%、成像 74.73% → 75.83% 也都改善（主体一致性和运动平滑度有轻微下降）。在标注为真值的 Sekai-Game 上：7.64 → 4.22，8.36 → 6.22，平均降幅超过 30%。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：世界探索需要的是长、连续、第一人称、且带逐帧相机位姿的视频，而现有数据集在这四条上同时不合格。Sekai 从 YouTube 采集 8623 小时行走与无人机素材，经镜头检测、转码、亮度/质量/字幕/轨迹四道过滤，得到 6620 小时 Sekai-Real，覆盖 101 个国家、750 座城市。标注包含位置（GPT-4o 抽取 + 区间树匹配）、四维类别与 176 词以上 caption（Qwen2.5-VL 72B）、以及 MegaSaM 估计的逐帧相机轨迹；另配一份用 UE5 游戏录制、位姿为真值的 Sekai-Game 作对照。采样模块按质量与四维多样性筛出 400 小时的 Sekai-Real-HQ 以适配算力预算。最有力的验证是相机控制实验：用真实标注位姿替代规则映射微调，无人机部分 TransErr 从 28.32 降到 17.19、游戏部分误差平均降超 30%。</p><p><strong>3 句话版</strong>：不是数据不够多，是标注维度不对——探索需要位姿标注，而没人在野外视频上做过。Sekai 用 MegaSaM + VLM 把这件事在 6620 小时规模上做完，并配一份游戏真值集做校验。相机控制误差近乎腰斩，证明位姿标注确实是缺失的那一环。</p><p><strong>1 句话版</strong>：给全球 citywalk 和无人机视频装上相机轨迹标签，世界探索模型就有了训练数据。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>MegaSaM 在野外手持/无人机视频上估计的相机轨迹足够准，可以当作训练监督信号使用</strong>。</p><p>这是整个数据集最核心的卖点，也是唯一一处&quot;标注质量决定数据价值&quot;的地方。位置和类别标注即使有 5–10% 错误也只影响条件文本，不至于毁掉模型；但位姿标注一旦系统性偏差，模型学到的就是错的相机-画面映射，而且这种错误在生成结果上很难被察觉。</p><p>论文为这个假设提供了什么证据？<strong>只有相对比较，没有绝对精度</strong>。作者在 200 条片段上比了 MegaSAM 与 VGGT，结论是&quot;MegaSAM 更平滑&quot;——但平滑不等于准确，一个系统性低估位移的估计器会非常平滑。作者自己也承认选择理由部分是&quot;更平滑的轨迹对模型训练更有利&quot;，这是一个偏向可训练性而非准确性的判据。</p><p>真正能验证绝对精度的资源其实就在手边：Sekai-Game 有 UE5 导出的真值位姿。<strong>在 Sekai-Game 上跑一遍 MegaSaM，与真值算 ATE/RPE</strong>，就能直接给出精度数字。论文没有报告这个实验，而它本可以是全文最有说服力的一张表。</p><p>间接的支持证据来自相机控制实验：用 Sekai-Real 无人机部分的 MegaSaM 标注微调，TransErr 显著下降。但要注意评测本身也用 Mega-SAM 从生成视频反解轨迹——<strong>训练标注和评测标注来自同一个估计器</strong>，如果 MegaSaM 有系统性偏差，模型学会复现这个偏差反而会让指标变好。Sekai-Game 上的实验（标注为真值、评测用 Mega-SAM）部分缓解了这个循环，但没有完全排除。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且直击 §9：</p><ul><li><strong>数据</strong>：不需要 Sekai。自己在任意 UE5 或 Unity 场景（或直接用 Habitat）里录 50 条 1 分钟的第一人称行走与飞行轨迹，导出真值相机位姿。刻意覆盖三档难度：平稳直行、边走边转头、快速大幅度机动。</li><li><strong>实现</strong>：按论文配置跑 MegaSaM（把 Depth Anything 换成 Video Depth Anything），得到估计轨迹。同时跑 VGGT 作对照。</li><li><strong>测量</strong>：对每条轨迹算 ATE 和相对位姿误差 RPE（平移与旋转分开），按难度分档统计；同时统计论文那三条过滤规则会剔除多少条。</li><li><strong>判据</strong>：如果平稳档 RPE 很小而机动档发散，说明 Sekai 的位姿标注质量与相机运动剧烈程度强相关——而论文的过滤规则恰好会把剧烈运动片段筛掉，这意味着<strong>数据集在&quot;精确标注&quot;和&quot;运动多样性&quot;之间做了一个未被明说的权衡</strong>：留下的都是好估计的，而好估计的往往运动单调。这个发现会直接影响下游模型能学到的动作范围。反之，如果三档 RPE 都很小，说明标注可靠，论文的价值主张成立。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释路线</strong>。相机控制实验的提升（TransErr 28.32 → 17.19）被归因于&quot;真实位姿标注优于规则映射&quot;。但有一个更平凡的解释：baseline 是<strong>未经任何领域微调</strong>的通用模型，而对照组在无人机视频上训了 2 个 epoch。无人机视频有极其鲜明的运动统计特征（连续平滑的大范围位移、几乎没有行人遮挡），只要在这个域上微调过，轨迹跟随就会变好，<strong>哪怕位姿标注质量一般</strong>。</p><p>验证设计：加一个第三组——用<strong>规则映射生成的位姿</strong>（即 baseline 的做法）在同一批 Sekai 无人机视频上微调同样的 2 个 epoch。三组对比后，&quot;域微调&quot;的贡献和&quot;标注质量&quot;的贡献才能被分离。如果第三组也能到 20 左右的 TransErr，那位姿标注的边际价值就远小于论文暗示的程度。</p><p><strong>可预测失败路线</strong>。数据构成本身预设了一个偏置：<strong>行走视频占 8409 小时，无人机只有 214 小时</strong>，而且相机控制实验只在无人机部分和游戏数据上做。原因不难猜——行走视频里人体的周期性起伏、频繁的转头、密集的动态行人，都会让 SfM 估计困难。可以预测：在 Sekai-Real 的<strong>行走部分</strong>上重复同一个相机控制实验，改善幅度会显著小于无人机部分，甚至可能在密集人群场景（数据集自带 crowd density 标签，正好可以分层）上失效。如果这一预测成立，那&quot;5000+ 小时&quot;这个数字的实际可用部分要大打折扣——真正能支撑相机可控训练的可能只是其中运动平稳、人少的那一小部分。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：Sekai 的位姿标注是<strong>无置信度的点估计</strong>。MegaSaM 输出一条轨迹，管线要么全盘接受，要么按三条手工规则整段丢弃。这既浪费了大量&quot;大部分片段可用、局部不可靠&quot;的数据，也让下游模型无法区分哪些监督信号该信、哪些该忽略。</p><p><strong>新 framing</strong>：把数据集从&quot;标注集合&quot;重新定义为&quot;<strong>带不确定性的监督分布</strong>&quot;，并让下游训练直接消费这个不确定性。相邻领域的现成工具是 SLAM 里的协方差传播与因子图边缘化——MegaSaM 内部本来就有全局优化模块，逐帧位姿的边缘协方差是可以被导出的，只是被丢掉了。</p><p>具体设想：给 Sekai 的每一帧位姿附一个协方差估计，训练时用它加权 Plücker embedding 的损失贡献——高不确定性帧的位姿条件被弱化甚至随机丢弃，低不确定性帧被强化。这不是&quot;加个模块&quot;，而是把数据集的契约从&quot;这是位姿&quot;改成&quot;这是位姿及我对它的信心&quot;，从而让<strong>数据清洗从二值筛选变成连续加权</strong>，那些因为局部抖动被整段丢弃的行走视频也能重新进入训练。</p><p><strong>第一个实验</strong>：不需要重训任何生成模型。先在 Sekai-Game（有真值）上验证前提——导出 MegaSaM 的逐帧不确定性代理（可以用全局优化的残差、或多次前馈的方差），检查它与真值 RPE 的相关性，画 sparsification curve。如果相关性显著，说明不确定性可估；下一步再验证按不确定性加权训练能否在同等数据量下降低 TransErr，或在放宽过滤规则、纳入更多原始数据后不劣化。</p>',57)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
